//! OpenAPI 3.1 spec + Swagger UI mount.
//!
//! Generated by [`utoipa`] from `#[utoipa::path]` annotations on handlers.
//! Served at (only when [`AppState::docs_enabled`] is `true`; config flag
//! `docs.enabled`, env `PHARMA__DOCS__ENABLED` — on a hardened on-prem box the
//! operator flips it off to keep the API surface off the wire):
//! * `/docs` — Swagger UI (HTML).
//! * `/docs/openapi.json` — raw spec.
//!
//! Schema strategy (Fase 11/erp-parity):
//! * The `ErrorEnvelope` envelope is registered with full `ToSchema`.
//! * Domain DTOs live in `crates/domain` which API mustn't touch this slice;
//!   their request/response bodies are surfaced as opaque `object` (via
//!   `body = serde_json::Value`) until a later PR brings `ToSchema` derives
//!   into the domain crate. Endpoint paths, methods, tags, security and
//!   error codes are all documented today — schemas come in the next slice.

use axum::Router;
use utoipa::{
    openapi::security::{HttpAuthScheme, HttpBuilder, SecurityScheme},
    Modify, OpenApi,
};
use utoipa_swagger_ui::SwaggerUi;

use crate::error::{ErrorBody, ErrorEnvelope};
use crate::AppState;

/// Mount point for the interactive Swagger UI.
pub const SWAGGER_UI_PATH: &str = "/docs";
/// Path the OpenAPI JSON is served at (and the URL Swagger UI fetches).
pub const OPENAPI_JSON_PATH: &str = "/docs/openapi.json";

/// Bearer-JWT security scheme injector. Registered as `bearer_jwt` so each
/// handler annotation can opt-in via `security(("bearer_jwt" = []))`.
pub struct SecurityAddon;

impl Modify for SecurityAddon {
    fn modify(&self, openapi: &mut utoipa::openapi::OpenApi) {
        if let Some(components) = openapi.components.as_mut() {
            components.add_security_scheme(
                "bearer_jwt",
                SecurityScheme::Http(
                    HttpBuilder::new()
                        .scheme(HttpAuthScheme::Bearer)
                        .bearer_format("JWT")
                        .description(Some(
                            "JWT HS256 emitido por `POST /api/v1/auth/login`. \
                             Claim `roles: [\"cashier\"|\"pharmacist\"|\"admin\"|\"owner\"]`.",
                        ))
                        .build(),
                ),
            );
        }
    }
}

