/// Build the Swagger UI + OpenAPI JSON sub-router, or an empty router when docs
/// are disabled (`docs.enabled = false`). Merged into the top-level router in
/// [`crate::build_router`]. When disabled, both `/docs` and
/// `/docs/openapi.json` 404 — keeps the API surface off the wire on hardened
/// on-prem deployments.
pub fn router(state: &AppState) -> Router<AppState> {
    if state.docs_enabled {
        SwaggerUi::new(SWAGGER_UI_PATH)
            .url(OPENAPI_JSON_PATH, ApiDoc::openapi())
            .into()
    } else {
        Router::new()
    }
}
